import itertools,json
jobs='ABCDE'
slot={'A':[0,1,4,11,3],'B':[2,3,3,2,5],'C':[4,8,2,10,8],'D':[3,2,11,3,4],'E':[10,6,10,10,4]}
trans=dict(zip(jobs,[[0,3,3,0,5],[5,0,4,2,0],[2,2,0,2,5],[0,5,5,0,5],[1,4,3,1,0]]))
def nominal(p):
 return sum(slot[j][i] for i,j in enumerate(p))+sum(trans[a][jobs.index(b)] for a,b in zip(p,p[1:]))
def incident(p,k):
 pos={j:p.index(j)+1 for j in jobs}
 if pos['A']>=pos['D']: return None
 if k=='rain':
  if pos['D']==1 or pos['A']==1:return None
  return nominal(p)+6*max(0,pos['C']-1)
 if k=='road':
  if pos['C']==4 or pos['E']==2:return None
  return nominal(p)+6*max(0,pos['D']-3)
 if k=='lift':
  if pos['A']==1 or pos['B']==1:return None
  return nominal(p)+10*max(0,pos['E']-2)
results=[]
for p in itertools.permutations(jobs):
 if p.index('A')>p.index('D'):continue
 neighbors=[(p,0)]
 for i,j in itertools.combinations(range(5),2):
  q=list(p);q[i],q[j]=q[j],q[i];neighbors.append((tuple(q),1))
 repairs={};costs={}
 for k in ['rain','road','lift']:
  valid=[(v+fee,''.join(q)) for q,fee in neighbors if (v:=incident(q,k)) is not None]
  if not valid:break
  costs[k],repairs[k]=min(valid)
 else:
  results.append({'roster':''.join(p),'score':nominal(p)+max(costs.values()),'repairs':repairs,'repair_costs':costs})
results.sort(key=lambda r:(r['score'],r['roster']))
answer=results[0].copy();answer['feasible_count']=len(results);answer['next_score']=min(r['score'] for r in results if r['score']>answer['score'])
print(json.dumps(answer))
print('optima',[(r['roster'],r['score']) for r in results if r['score']==answer['score']])
print('published_nominal',nominal(tuple(answer['roster'])))

